ublic/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_P04.mp3?v=20260927-ready","exampleAudioId":"A2_MOVE_E04","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_E04.mp3?v=20260927-ready"},{"id":"A2_MOVE_P05","mediaRef":"A2_MOVE_P05","text":"move into","exampleMediaRef":"A2_MOVE_E05","example":"We moved into the room.","audioId":"A2_MOVE_P05","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_P05.mp3?v=20260927-ready","exampleAudioId":"A2_MOVE_E05","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_E05.mp3?v=20260927-ready"},{"id":"A2_MOVE_P06","mediaRef":"A2_MOVE_P06","text":"come out of","exampleMediaRef":"A2_MOVE_E06","example":"The girl came out of the tent.","audioId":"A2_MOVE_P06","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_P06.mp3?v=20260927-ready","exampleAudioId":"A2_MOVE_E06","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_E06.mp3?v=20260927-ready"},{"id":"A2_MOVE_P07","mediaRef":"A2_MOVE_P07","text":"run around","exampleMediaRef":"A2_MOVE_E07","example":"The dog ran around the tree.","audioId":"A2_MOVE_P07","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_P07.mp3?v=20260927-ready","exampleAudioId":"A2_MOVE_E07","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-1/m1/l2/listen-repeat/A2_MOVE_E07.mp3?v=20260927-ready"}]}},{"role":"practice","exercise":{"version":1,"id":"A2_MOVE_M05","kind":"gaps","title":"Choose the correct preposition.","inputMode":"select","items":[{"id":"1","segments":["The boy climbed ",{"id":"A2_MOVE_M05-1","options":["into","over","out of"],"answers":["over"]}," the fence and got to the other side."]},{"id":"2","segments":["She was on the ground. She stepped ",{"id":"A2_MOVE_M05-2","options":["onto","around","out of"],"answers":["onto"]}," the low platform. Now she was standing on it."]},{"id":"3","segments":["The dog was inside the tunnel. I was waiting by the entrance. It came ",{"id":"A2_MOVE_M05-3","options":["onto","into","out of"],"answers":["out of"]}," the tunnel and ran towards me."]},{"id":"4","segments":["We climbed ",{"id":"A2_MOVE_M05-4","options":["into","out of","up"],"answers":["up"]}," the hill until we reached the top."]},{"id":"5","segments":["We were outside the house. It started to rain, so we moved ",{"id":"A2_MOVE_M05-5","options":["into","over","around"],"answers":["into"]}," the kitchen."]},{"id":"6","segments":["The dog ran ",{"id":"A2_MOVE_M05-6","options":["around","into","over"],"answers":["around"]}," the tree in a circle."]},{"id":"7","segments":["She jumped ",{"id":"A2_MOVE_M05-7","options":["around","over","out of"],"answers":["over"]}," the puddle and landed on the other side."]}]}},{"role":"rule","exercise":{"version":1,"id":"A2_MOVE_M04-rule-homework-rule","kind":"rule-page","title":"Read the examples and choose the meaning.","blocks":[{"type":"rule","title":"Как описать направление движения","text":"Глагол показывает способ движения, а предлог — путь. Climb up the ladder — подняться по лестнице вверх. Climb over the wall — перелезть через стену на другую сторону. Если препятствие преодолевают прыжком, используйте jump over: She jumped over the log.\n\nOnto показывает переход на поверхность: She stepped onto the rock. Сравните: She is on the rock описывает положение, а не переход.\n\nInto показывает перемещение внутрь: It started to rain, so we moved into the tent. Здесь move into означает «переместиться внутрь», не «переехать жить». Out of показывает обратное направление: I was outside when she came out of the tent. Перед названием места сохраняйте обе части: out of the tent.\n\nAround описывает движение вокруг предмета или в обход него. Полный круг необязателен: The dog ran around the tree to reach its ball. Предлог не меняется из-за времени; форму времени получает глагол: run → ran, come → came.","highlights":["Climb up the ladder","Climb over the wall","jump over","She jumped over the log.","Onto","She stepped onto the rock.","She is on the rock","Into","It started to rain, so we moved into the tent.","Out of","I was outside when she came out of the tent.","out of the tent","Around","The dog ran around the tree to reach its ball.","run → ran","come → came"]}]}},{"role":"translation","exercise":{"version":1,"id":"A2_MOVE_HW1","kind":"writing","title":"Translate into English.","instruction":"Переведите предложения на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Марк взобрался по лестнице.","normalization":"translation","acceptedAnswers":["Mark climbed up the ladder.","Mark climbed up a ladder.","Mark climbed up the stairs."],"placeholder":"Mark"},{"id":"2","prompt":"Анна перепрыгнула через лужу.","normalization":"translation","acceptedAnswers":["Anna jumped over the puddle.","Anna jumped over a puddle."],"placeholder":"Anna"},{"id":"3","prompt":"Бен шагнул на платформу.","normalization":"translation","acceptedAnswers":["Ben stepped onto the platform.","Ben stepped onto a platform.","Ben stepped on to the platform.","Ben stepped on to a platform."],"placeholder":"Ben"},{"id":"4","prompt":"Мы переместились в гараж.","normalization":"translation","acceptedAnswers":["We moved into the garage.","We moved into a garage."]},{"id":"5","prompt":"Собака вышла из туннеля.","normalization":"translation","acceptedAnswers":["The dog came out of the tunnel.","The dog came out of a tunnel.","The dog went out of the tunnel.","The dog went out of a tunnel.","The dog walked out of the tunnel.","The dog walked out of a tunnel.","A dog came out of the tunnel.","A dog came out of a tunnel.","A dog went out of the tunnel.","A dog went out of a tunnel.","A dog walked out of the tunnel.","A dog walked out of a tunnel."]},{"id":"6","prompt":"Дети бегали вокруг дерева.","normalization":"translation","acceptedAnswers":["The children ran around the tree.","The children ran around a tree.","The children ran round the tree.","The children ran round a tree.","Children ran around the tree.","Children ran around a tree.","Children ran round the tree.","Children ran round a tree.","The kids ran around the tree.","The kids ran around a tree.","The kids ran round the tree.","The kids ran round a tree.","Kids ran around the tree.","Kids ran around a tree.","Kids ran round the tree.","Kids ran round a tree."]}]}},{"role":"translation","exercise":{"version":1,"id":"A2_MOVE_HW2","kind":"writing","title":"Translate into English.","instruction":"Переведите предложения на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Поднимись по стене до самого верха.","normalization":"translation","acceptedAnswers":["Climb up the wall to the top.","Climb up the wall all the way to the top.","Climb up the wall until you reach the top.","Climb up a wall to the top.","Climb up a wall all the way to the top.","Climb up a wall until you reach the top."]},{"id":"2","prompt":"Не прыгай через это бревно.","normalization":"translation","acceptedAnswers":["Do not jump over this log."]},{"id":"3","prompt":"Она шагнула на низкий ящик.","normalization":"translation","acceptedAnswers":["She stepped onto the low box.","She stepped onto a low box.","She stepped on to the low box.","She stepped on to a low box."]},{"id":"4","prompt":"Они переместились внутрь здания.","normalization":"translation","acceptedAnswers":["They moved into the building.","They moved into a building."]},{"id":"5","prompt":"Том вышел из палатки.","normalization":"translation","acceptedAnswers":["Tom came out of the tent.","Tom came out of a tent.","Tom went out of the tent.","Tom went out 