ни получает глагол: run → ran, come → came.","highlights":["Climb up the ladder","Climb over the wall","jump over","She jumped over the log.","Onto","She stepped onto the rock.","She is on the rock","Into","It started to rain, so we moved into the tent.","Out of","I was outside when she came out of the tent.","out of the tent","Around","The dog ran around the tree to reach its ball.","run → ran","come → came"]}]},"exercises":[{"version":1,"id":"A2_MOVE_M02-match","kind":"matching","title":"Match the pictures with the phrases.","layout":"picture-word","items":[{"id":"A2_MOVE_IMG01","mediaRef":"A2_MOVE_IMG01","text":"Picture 1","correctId":"move-into","assetId":"A2_MOVE_IMG01","alt":"Picture 1","image":"assets/lesson-media/a2-1/module-1/smy-2/images/movement-01.webp","imageWidth":352,"imageHeight":420},{"id":"A2_MOVE_IMG02","mediaRef":"A2_MOVE_IMG02","text":"Picture 2","correctId":"jump-over","assetId":"A2_MOVE_IMG02","alt":"Picture 2","image":"assets/lesson-media/a2-1/module-1/smy-2/images/movement-02.webp","imageWidth":352,"imageHeight":420},{"id":"A2_MOVE_IMG03","mediaRef":"A2_MOVE_IMG03","text":"Picture 3","correctId":"run-around","assetId":"A2_MOVE_IMG03","alt":"Picture 3","image":"assets/lesson-media/a2-1/module-1/smy-2/images/movement-03.webp","imageWidth":352,"imageHeight":420},{"id":"A2_MOVE_IMG04","mediaRef":"A2_MOVE_IMG04","text":"Picture 4","correctId":"climb-up","assetId":"A2_MOVE_IMG04","alt":"Picture 4","image":"assets/lesson-media/a2-1/module-1/smy-2/images/movement-04.webp","imageWidth":352,"imageHeight":420},{"id":"A2_MOVE_IMG05","mediaRef":"A2_MOVE_IMG05","text":"Picture 5","correctId":"come-out-of","assetId":"A2_MOVE_IMG05","alt":"Picture 5","image":"assets/lesson-media/a2-1/module-1/smy-2/images/movement-05.webp","imageWidth":352,"imageHeight":420},{"id":"A2_MOVE_IMG06","mediaRef":"A2_MOVE_IMG06","text":"Picture 6","correctId":"step-onto","assetId":"A2_MOVE_IMG06","alt":"Picture 6","image":"assets/lesson-media/a2-1/module-1/smy-2/images/movement-0