insert into homework_private.templates(lesson_id,definition) values ('a2-1-w1-smy-3','{"id":"a2-1-w1-smy-3","version":"20261004-a21","level":"A2.1","title":"Подскажите, как пройти…","steps":[{"role":"words","exercise":{"version":1,"id":"A2_DIR_M02-match","kind":"matching","title":"Match the phrases with their meanings.","items":[{"id":"along","text":"go along","correctId":"along"},{"id":"across","text":"walk across","correctId":"across"},{"id":"straight","text":"keep going straight","correctId":"straight"},{"id":"through","text":"continue through","correctId":"through"},{"id":"towards","text":"head towards","correctId":"towards"},{"id":"past","text":"walk past","correctId":"past"},{"id":"down","text":"go down","correctId":"down"}],"options":[{"id":"towards","text":"move in the direction of a place"},{"id":"across","text":"walk from one side to the other side of an open space or a bridge"},{"id":"down","text":"move from a higher place to a lower place"},{"id":"along","text":"follow the length of a road or path"},{"id":"past","text":"walk by a place and continue beyond it"},{"id":"straight","text":"continue without turning left or right"},{"id":"through","text":"carry on inside a place and leave it on the other side"}]}},{"role":"listenRepeat","exercise":{"version":1,"id":"A2_DIR_M03","kind":"audio","title":"Listen and repeat.","layout":"listen-repeat","instruction":"Listen and repeat each phrase.","items":[{"id":"A2_DIR_P01","text":"Go along River Street.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P01_r1.mp3"},{"id":"A2_DIR_P02","text":"Walk across the bridge.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P02_r1.mp3"},{"id":"A2_DIR_P03","text":"Keep going straight.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P03_r1.mp3"},{"id":"A2_DIR_P04","text":"Continue through the park.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P04_r1.mp3"},{"id":"A2_DIR_P05","text":"Head towards the fountain.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P05_r1.mp3"},{"id":"A2_DIR_P06","text":"Walk past the bank.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P06_r1.mp3"},{"id":"A2_DIR_P07","text":"Go down the stairs.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P07_r1.mp3"},{"id":"A2_DIR_P08","text":"Pass the café.","audio":"assets/lesson-media/a2-1/module-1/smy-3/audio/A2_DIR_P08_r1.mp3"}]}},{"role":"practice","exercise":{"version":1,"id":"A2_DIR_M05","kind":"gaps","title":"Choose the correct words.","inputMode":"select","items":[{"id":"1","segments":["The café is on the opposite side of the square. Walk ",{"id":"A2_DIR_G1","options":["past","across","towards"],"answers":["across"]}," the square to get to that side."]},{"id":"2","segments":["Stay outside the shop. Walk ",{"id":"A2_DIR_G2","options":["through","across","past"],"answers":["past"]}," it and stop at the next building."]},{"id":"3","segments":["Enter the park at this gate and leave by the gate on the other side. Continue ",{"id":"A2_DIR_G3","options":["through","past","towards"],"answers":["through"]}," the park."]},{"id":"4","segments":["You are on the upper path; the café is on the lower path. Go ",{"id":"A2_DIR_G4","options":["across","down","past"],"answers":["down"]}," the stairs to the café."]},{"id":"5","segments":["Stay on this road as it follows the river. Go ",{"id":"A2_DIR_G5","options":["across","through","along"],"answers":["along"]}," River Street until you reach the bridge."]},{"id":"6","segments":["Do not turn at the crossing. Keep ",{"id":"A2_DIR_G6","options":["go straight","going straight","to go straight"],"answers":["going straight"]}," until you reach the bank."]},{"id":"7","segments":["The cinema is the building after the café. ",{"id":"A2_DIR_G7","options":["Pass","Pass past","Pass towards"],"answers":["Pass"]}," the café and stop at the cinema."]}]}},{"role":"rule","exercise":{"version":1,"id":"A2_DIR_M04-rule-homework-rule","kind":"rule-page","title":"How to give directions.","blocks":[{"type":"rule","title":"","text":"Чтобы объяснить дорогу, используйте глагол в начальной форме без подлежащего: Go along River Street. Знакомые turn left / turn right помогают соединять участки маршрута.\n\nGo along — двигаться вдоль улицы, дорожки или реки. Walk across — пересечь открытое пространство или мост с одной стороны на другую. Continue through — продолжить путь через внутреннюю часть пространства: Continue through the park.\n\nWalk past — пройти мимо объекта и дальше: Walk past the bank. Глагол pass в этом значении уже содержит идею «пройти мимо»: Pass the bank. После pass не нужен past. Head towards — направляться к ориентиру: Head towards the fountain. Эта фраза не сообщает, что вы уже дошли до него; можно повернуть раньше.\n\nKeep going straight — продолжать прямо, не сворачивая. После keep здесь используется going: Keep going straight. После continue можно сказать through the park; также возможно continue walking. Head здесь — глагол «направляться», а не существительное «голова».\n\nGo down the stairs — спуститься по лестнице. В сочетании go down the street слово down может означать движение по улице и не обязательно указывает на склон. В упражнениях этого урока спуск показан лестницей.\n\nЭти описания могут сочетаться: Go along the street описывает путь относительно улицы, а Keep going straight — отсутствие поворота. Один и тот же участок может подходить к обеим фразам. Это не взаимоисключающие значения. Straight употребляется без объекта; после along / across / through / past / towards в изучаемых сочетаниях называем ориентир.","highlights":["Go along","Walk across","Continue through","Walk past","Pass the bank.","Head towards","Keep going straight","Go down the stairs","go down the street"]}]}},{"role":"translation","exercise":{"version":1,"id":"A2_DIR_HW1","kind":"writing","title":"Translate into English.","instruction":"Переведите предложения на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Идите вдоль Кинг-стрит до моста.","normalization":"translation","acceptedAnswers":["Go along King Street to the bridge.","Go along King Street until you reach the bridge.","Go along King Street as far as the bridge.","Walk along King Street to the bridge.","Walk along King Street until you reach the bridge.","Walk along King Street as far as the bridge."],"placeholder":"King Street"},{"id":"2","prompt":"Перейдите мост на другую сторону.","normalization":"translation","acceptedAnswers":["Walk across the bridge to the other side.","Walk across the bridge.","Go across the bridge to the other side.","Go across the bridge.","Cross the bridge to the other side.","Cross the bridge."]},{"id":"3","prompt":"На перекрёстке продолжайте идти прямо.","normalization":"translation","acceptedAnswers":["Keep going straight at the intersection.","Keep going straight at the crossroads.","Keep going straight at the crossing.","Continue straight at the intersection.","Continue straight at the crossroads.","Continue straight at the crossing.","Continue going straight at the intersection.","Continue going straight at the crossroads.","Continue going straight at the crossing.","At the intersection keep going straight.","At the intersection continue straight.","At the intersection continue going straight.","At the crossroads keep going straight.","At the crossroads continue straight.","At the crossroads continue going straight.","At the crossing keep going straight.","At the crossing continue straight.","At the crossing continue going straight."]},{"id":"4","prompt":"Пройдите через парк.","normalization":"translation","acceptedAnswers":["Continue through the park.","Walk through the park.","Go through the park."]},{"id":"5","prompt":"Направляйтесь к фонтану.","normalization":"translation","acceptedAnswers":["Head towards the fountain.","Head toward the fountain.","Go towards the fountain.","Go toward the fountain.","Walk towards the fountain.","Walk toward the fountain."]},{"id":"6","prompt":"Пройдите мимо банка.","normalization":"translation","acceptedAnswers":["Walk past the bank.","Go past the bank.","Pass the bank."]}]}},{"role":"translation","exercise":{"version":1,"id":"A2_DIR_HW2","kind":"writing","title":"Translate into English.","instruction":"Переведите предложения на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Спуститесь по лестнице и поверните направо.","normalization":"translation","acceptedAnswers":["Go down the stairs and turn right.","Walk down the stairs and turn right.","Go downstairs and turn right.","Walk downstairs and turn right."]},{"id":"2","prompt":"Пройдите мимо магазина и остановитесь у кинотеатра.","normalization":"translation","acceptedAnswers":["Walk past the shop and stop at the cinema.","Walk past the shop and stop at the movie theater.","Walk past the shop and stop at the movie theatre.","Walk past the shop and stop by the cinema.","Walk past the shop and stop by the movie theater.","Walk past the shop and stop by the movie theatre.","Walk past the shop and stop outside the cinema.","Walk past the shop and stop outside the movie theater.","Walk past the shop and stop outside the movie theatre.","Walk past the store and stop at the cinema.","Walk past the store and stop at the movie theater.","Walk past the store and stop at the movie theatre.","Walk past the store and stop by the cinema.","Walk past the store and stop by the movie theater.","Walk past the store and stop by the movie theatre.","Walk past the store and stop outside the cinema.","Walk past the store and stop outside the movie theater.","Walk past the store and stop outside the movie theatre.","Go past the shop and stop at the cinema.","Go past the shop and stop at the movie theater.","Go past the shop and stop at the movie theatre.","Go past the shop and stop by the cinema.","Go past the shop and stop by the movie theater.","Go past the shop and stop by the movi